import limited_client as robot,numpy as np
o=robot.observe('corner'); T=o['camera_to_world']; K=o['intrinsic']; d=o['depth_m']
for v in range(185,221,5):
 for u in range(185,241,5):
  col=o['rgb'][v,u]; z=float(d[v,u]);
  if col[0]-col[1] < 20 and col[1]-col[2] <20 and col[0]>45:
   w=T[:3,:3]@(np.linalg.inv(K)@np.array([u,v,1])*z)+T[:3,3]; print((u,v),tuple(col),round(z,2),np.round(w,3))
PY

